(function(){
'use strict';
let dbPromise,recorder=null,stream=null,chunks=[],started=0,clock=null,recordPage='',recordTitle='',host=null,urls=[],saving=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function pageName(key){const p=key.split(':');if(p[0]==='unix')return `유닉스 프로그래밍 · ${p[1]} · ${p[2]}쪽`;if(p[0]==='course'){let name='학습 과목';try{name=JSON.parse(localStorage.getItem('study-library-v1'))?.courses?.find(c=>c.id===p[1])?.name||(p[1]==='programming-languages'?'프로그래밍언어론':name);}catch{}const ch=window.COURSE_CHAPTERS?.find(c=>c.id===p[2]);return `${name} · ${ch?.title||'강의자료'} · ${p[3]}쪽`;}return '전체 서재';}
const badge=document.createElement('div');badge.id='notebook-recording-badge';badge.hidden=true;badge.innerHTML='<span role="status"></span><button type="button">녹음 종료</button>';document.body.append(badge);
function activate(button,fn){let touch=-1000;button.onclick=e=>{if(e.detail>0&&performance.now()-touch<600)return;fn(e);};button.addEventListener('pointerup',e=>{if(e.pointerType!=='mouse'){e.preventDefault();touch=performance.now();button.click();}});}
activate(badge.querySelector('button'),stop);
function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('study-audio-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('clips',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('녹음 보관함을 열지 못했습니다.'));});}
async function write(clip){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('clips','readwrite');tx.objectStore('clips').put(clip);tx.oncomplete=resolve;tx.onabort=tx.onerror=()=>reject(Error('녹음을 저장하지 못했습니다. 저장 공간을 확인하고 아래 파일을 내려받으세요.'));});}
async function all(){const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction('clips').objectStore('clips').getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>b.created-a.created));r.onerror=()=>reject(Error('녹음 목록을 읽지 못했습니다.'));});}
function message(text){if(host?.isConnected)host.querySelector('#audio-status').textContent=text;}
function release(){stream?.getTracks().forEach(t=>t.stop());stream=null;clearInterval(clock);clock=null;badge.hidden=true;}
function elapsed(){const s=Math.floor((Date.now()-started)/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}
function update(){const running=recorder?.state==='recording';badge.hidden=!running;if(running)badge.querySelector('span').textContent='● 녹음 중 '+elapsed();if(host?.isConnected){host.querySelector('#audio-start').disabled=running||saving;host.querySelector('#audio-stop').disabled=!running;host.querySelector('#audio-live').textContent=running?'● 녹음 중 '+elapsed()+'':saving?'녹음을 저장하는 중…':'';}}
async function start(){if(recorder?.state==='recording'||saving)return;if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){message('이 브라우저에서는 마이크 녹음을 사용할 수 없습니다. 녹음 파일 등록은 사용할 수 있습니다. Safari에서 사이트를 직접 열어 보세요.');return;}saving=true;update();try{stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});const types=['audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'];const mime=types.find(t=>MediaRecorder.isTypeSupported(t));recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);chunks=[];recordPage=window.Notebook.getPageKey();recordTitle=host.querySelector('#audio-title').value.trim()||'학습 녹음';started=Date.now();let total=0;recorder.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);total+=e.data.size;if(total>100*1024*1024&&recorder.state==='recording'){message('100MB에 도달하여 녹음을 종료합니다.');stop();}}};recorder.onerror=e=>{message('녹음 중 오류가 발생했습니다. 수집된 부분이 있으면 저장을 시도합니다.');if(recorder.state!=='inactive')recorder.stop();else release();};recorder.onstop=async()=>{const mime=recorder.mimeType||chunks[0]?.type||'audio/webm',blob=new Blob(chunks,{type:mime}),duration=Date.now()-started;release();saving=true;update();if(blob.size){const ext=mime.includes('mp4')?'m4a':mime.includes('ogg')?'ogg':'webm';const clip={id:crypto.randomUUID(),page:recordPage,title:recordTitle,filename:recordTitle+'.'+ext,created:Date.now(),duration,blob};try{await write(clip);message('저장됨');await renderList();}catch(e){message(e.message);if(host?.isConnected){const a=document.createElement('a'),url=URL.createObjectURL(blob);urls.push(url);a.href=url;a.download=clip.filename;a.textContent='저장되지 않은 녹음 내려받기';host.querySelector('#audio-recovery').append(a);}}}else message('녹음 데이터가 없습니다. 마이크 입력 상태를 확인하세요.');saving=false;update();};recorder.start(1000);saving=false;clock=setInterval(update,500);message('녹음 중');update();}catch(e){release();saving=false;message(e.name==='NotAllowedError'?'마이크 권한이 거부되었거나 브라우저가 허용하지 않습니다. 사이트 권한을 확인하거나 Safari에서 직접 열어 주세요.':e.name==='NotFoundError'?'사용할 수 있는 마이크를 찾지 못했습니다.':'녹음을 시작하지 못했습니다: '+e.message);update();}}
function stop(){if(recorder?.state==='recording'){recorder.stop();release();saving=true;update();}}
async function renderList(){if(!host?.isConnected)return;const root=host;try{const clips=await all();if(root!==host)return;root.querySelectorAll('audio').forEach(a=>a.pause());urls.forEach(URL.revokeObjectURL);urls=[];const showAll=root.querySelector('#audio-all').checked,page=window.Notebook.getPageKey(),list=clips.filter(c=>showAll||c.page===page),box=root.querySelector('#audio-list');box.innerHTML=list.length?'':'<p>등록된 녹음이 없습니다.</p>';for(const clip of list){const row=document.createElement('article'),url=URL.createObjectURL(clip.blob);urls.push(url);row.className='audio-clip';row.innerHTML=`<h4>${esc(clip.title)}</h4><p>${new Date(clip.created).toLocaleString('ko-KR')} · ${(clip.blob.size/1024/1024).toFixed(2)}MB</p><small>연결 위치: ${esc(pageName(clip.page))}</small><audio controls preload="metadata" src="${url}"></audio><p class="audio-play-error" role="status"></p><a href="${url}" download="${esc(clip.filename)}">녹음 내려받기</a> <button type="button">삭제</button>`;row.querySelector('audio').onerror=()=>row.querySelector('.audio-play-error').textContent='이 브라우저가 이 파일의 재생 형식을 지원하지 않을 수 있습니다. 내려받아 재생해 주세요.';activate(row.querySelector('button'),async()=>{try{const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('clips','readwrite');tx.objectStore('clips').delete(clip.id);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('삭제하지 못했습니다.'));});await renderList();message('삭제됨');}catch(e){message(e.message);}});box.append(row);}}catch(e){message(e.message);}}
function mount(element){host=element;host.innerHTML=`<details class="audio-help"><summary>보관 안내</summary><p>녹음과 등록 파일은 이 브라우저에만 보관됩니다. 서버 업로드·기기 간 동기화는 하지 않습니다. 중요한 녹음은 내려받아 보관하고, 페이지를 닫기 전에 녹음 종료·저장을 눌러 주세요.</p></details><label>녹음 제목<input id="audio-title" maxlength="150" placeholder="예: 구문 7장 복습"></label><div class="notebook-actions"><button type="button" id="audio-start">녹음 시작</button><button type="button" id="audio-stop" disabled>녹음 종료·저장</button></div><p id="audio-live" role="status"></p><label>녹음 파일 등록<input id="audio-upload" type="file" accept="audio/*,.m4a,.mp3,.wav,.ogg,.webm,.aac,.mp4" multiple></label><small>파일당 최대 100MB · 현재 페이지에 연결합니다.</small><p id="audio-status" role="status"></p><div id="audio-recovery"></div><label><input id="audio-all" type="checkbox"> 모든 페이지 녹음 보기</label><div id="audio-list"></div>`;activate(host.querySelector('#audio-start'),start);activate(host.querySelector('#audio-stop'),stop);host.querySelector('#audio-all').onchange=renderList;host.querySelector('#audio-upload').onchange=async e=>{const files=[...e.target.files],page=window.Notebook.getPageKey();for(const f of files){if(f.size>100*1024*1024){message(f.name+': 100MB 이하로 등록해 주세요.');continue;}if(!f.size||!(/\.(mp3|m4a|wav|ogg|webm|aac|mp4)$/i.test(f.name)||f.type.startsWith('audio/'))){message(f.name+': 오디오 파일을 선택해 주세요.');continue;}try{await write({id:crypto.randomUUID(),page,title:f.name,filename:f.name,created:Date.now(),blob:f});message('등록됨');}catch(err){message(err.message);}}e.target.value='';await renderList();};update();renderList();}
window.addEventListener('beforeunload',e=>{if(recorder?.state==='recording'||saving){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{if(recorder?.state==='recording')recorder.stop();release();});
window.StudyAudio={mount};
})();
